def run(fn,n,trials=40):
    bb=None
    for trial in range(trials):
        x0=rng.uniform(0.1,2,n)
        try:
            r=least_squares(lambda q: fn(q)-y, x0, max_nfev=3000)
        except Exception: continue
        if not np.all(np.isfinite(r.fun)): continue
        if bb is None or r.cost<bb.cost: bb=r
