def fA(q):
    a,b,s0,r0,r1,K0,K1=q
    g=g_(a,b)
    return s0*g + (r0+r1*t)*P*(1-P/(K0+K1*t))
def fB(q):
    a,b,s0,r0,r1,K0,K1,A=q
    g=g_(a,b)
    return s0*g + (r0+r1*t)*P*(1-P/(K0+K1*t))*(P/A-1)
def fC(q):
    a,b,s0,r0,r1,K0,K1,s1=q
    g=g_(a,b)
    return s0*g + s1*g*P + (r0+r1*t)*P*(1-P/(K0+K1*t))
def fD(q):
    a,b,s0,r0,r1,K0,K1,c=q
    g=g_(a,b)
    return s0*g + r0*P*(1-P/(K0+K1*t)) + r1*t*P*(1-P/(K0+K1*t))  + c*P**2*t
